-- Migration 021: Document Templates (Invoice + Certificate of Completion)
-- Adds a single templates table used by both the Invoice and COC PDF generators.
-- Each template carries the company branding (logo, company info, primary color),
-- default line items (for invoice), default terms/sales rep, signature config,
-- and a per-template toggle for the "Generated by Sietch CRM" footer text.
-- A single template can be reused for either document type.

CREATE TABLE IF NOT EXISTS document_templates (
    id                       SERIAL PRIMARY KEY,
    name                     TEXT NOT NULL,
    logo_path                TEXT,
    company_name             TEXT NOT NULL DEFAULT '',
    company_address          TEXT NOT NULL DEFAULT '',
    company_city_state_zip   TEXT NOT NULL DEFAULT '',
    company_phone            TEXT NOT NULL DEFAULT '',
    company_email            TEXT NOT NULL DEFAULT '',
    primary_color            TEXT NOT NULL DEFAULT '#1a1a1a',
    invoice_title            TEXT NOT NULL DEFAULT 'INVOICE',
    coc_title                TEXT NOT NULL DEFAULT 'CERTIFICATE OF COMPLETION',
    default_terms            TEXT NOT NULL DEFAULT 'Due on receipt',
    default_sales_rep        TEXT NOT NULL DEFAULT '',
    default_line_items       JSONB NOT NULL DEFAULT '[]'::jsonb,
    show_signature           BOOLEAN NOT NULL DEFAULT TRUE,
    signature_name           TEXT NOT NULL DEFAULT '',
    signature_path           TEXT,
    show_branding_footer     BOOLEAN NOT NULL DEFAULT TRUE,
    is_default               BOOLEAN NOT NULL DEFAULT FALSE,
    created_at               TIMESTAMP DEFAULT NOW(),
    updated_at               TIMESTAMP DEFAULT NOW()
);

-- Additive ALTER for databases that already created the table before the
-- show_branding_footer column was added. Idempotent.
ALTER TABLE document_templates
    ADD COLUMN IF NOT EXISTS show_branding_footer BOOLEAN NOT NULL DEFAULT TRUE;

CREATE INDEX IF NOT EXISTS idx_document_templates_default
    ON document_templates(is_default) WHERE is_default = TRUE;

-- Notes:
--   * default_line_items shape: [{description: str, amount: number}, ...]
--   * logo_path / signature_path are repo-relative paths under data/logos/
--   * show_branding_footer toggles the "Generated by Sietch CRM" footer text
--     on the COC PDF; invoice footer just shows job # + page X of Y.
--   * is_default = only one row should be TRUE at any time; the API enforces this